package com.vikash.bedtimestories.data

/**
 * A second set of traditional tales (Panchatantra, Hitopadesha, Jataka and
 * well-known fables), retold gently for bedtime. This file holds the English
 * text and the pictures; every other language lives in a `TALES2_XX` map keyed
 * by the same story ids. As in the first set, harsh endings are softened.
 */
internal object ClassicTales2 {

    private fun tale(
        id: String, scene: Scene, mood: Mood, cover: String, title: String, moral: String,
        vararg pages: Pair<String, String>,
    ) = Story(id, title, mood, scene, cover, moral, pages.map { (art, text) -> Page(text, art) }, classic = true)

    val base: List<Story> = listOf(
        tale(
            "golden-eggs", Scene.MEADOW, Mood.CALM, "hen egg",
            "The Hen and the Golden Eggs", "Good things come to those who wait patiently.",
            "boy hen" to "A farmer had a little white hen. One morning he found something shining in her nest. It was an egg made of gold!",
            "hen egg" to "Every morning after that, the hen laid one golden egg. The farmer was happy, and the hen was happy too.",
            "boy hen" to "But soon the farmer grew impatient. “One egg a day is too slow,” he said. “I want all the eggs at once!” He chased the hen round and round the yard.",
            "hen" to "The hen was frightened. She flew up into a tall tree and would not come down. The next morning there was no egg at all.",
            "boy hen egg" to "The farmer said sorry and scattered some grain. Slowly the hen came home. After that he waited kindly each day, and each day there was one golden egg.",
        ),
        tale(
            "two-goats", Scene.RIVER, Mood.FRIENDSHIP, "goat goat",
            "The Two Goats on the Bridge", "When we make way for each other, everyone gets across.",
            "goat" to "A narrow log lay across a river. It was so narrow that only one goat could cross at a time.",
            "goat goat" to "One day two goats stepped onto the log, one from each side. They met in the middle. Neither one could pass.",
            "goat goat" to "“Go back,” said the first goat. “No, you go back,” said the second. They lowered their horns. The log began to wobble.",
            "goat goat" to "Then the first goat stopped. “If we fight, we will both fall in,” she said. “I have an idea. I will lie down, and you can step over me.”",
            "goat goat" to "She lay down flat. The second goat stepped gently over her. “Thank you,” he said. Both goats crossed safely, and both went home dry.",
        ),
        tale(
            "moon-lake", Scene.NIGHT, Mood.WISDOM, "rabbit elephant",
            "The Rabbit and the Moon Lake", "A clever and gentle word can do what strength cannot.",
            "elephant" to "One dry summer, a herd of elephants found a cool lake. Every day they came to drink, with their great heavy feet.",
            "rabbit rabbit" to "A family of rabbits lived beside that lake. The elephants did not see them, and the rabbits had to hop away quickly, again and again.",
            "rabbit elephant" to "That night a small rabbit went to the elephant king. “The Moon sends me,” said the rabbit. “This is the Moon’s own lake. Come and see.”",
            "elephant rabbit" to "The elephant king looked into the water. There was the moon, shining. He touched the water with his trunk, and the moon trembled and shook.",
            "rabbit rabbit" to "“The Moon is upset,” whispered the rabbit. The elephant king bowed. “We will drink at the far lake,” he said. And the rabbits slept safely beside the water.",
        ),
        tale(
            "grandmother-bell", Scene.JUNGLE, Mood.COURAGE, "painter bell",
            "The Brave Grandmother and the Bell", "Look carefully before you believe a frightening story.",
            "bell" to "Every evening a bell rang in the forest. Ting, ting, ting. Nobody knew who was ringing it.",
            "boy" to "“It is a monster!” said the people of the village. They locked their doors at sunset. Nobody would go near the forest.",
            "painter" to "But one grandmother was not so sure. “I have never seen a monster,” she said. “I will go and look.” She took a basket of fruit and walked into the trees.",
            "monkey bell" to "There, on a branch, sat a little monkey, shaking a bell and laughing. The grandmother put the fruit on the ground.",
            "painter bell monkey" to "The monkey dropped the bell and ran to the fruit. The grandmother carried the bell home. Everyone laughed, and that night the village slept with open windows.",
        ),
        tale(
            "belling-cat", Scene.NIGHT, Mood.WISDOM, "mouse bell cat",
            "Who Will Bell the Cat?", "A plan is only good if somebody can carry it out.",
            "mouse mouse mouse" to "A family of mice lived in an old house. A big cat lived there too, and she walked so softly that the mice never heard her coming.",
            "mouse mouse" to "One night the mice held a meeting. “We must do something,” they said. Everyone thought very hard.",
            "mouse bell" to "A young mouse jumped up. “Let us tie a bell around the cat’s neck! Then we will always hear her.” All the mice cheered.",
            "mouse cat~" to "Then the oldest mouse asked quietly, “It is a fine idea. But who will tie the bell on the cat?” Nobody answered. Nobody moved.",
            "mouse mouse house" to "So the mice made a new plan, one they could really do. They dug a tiny back door, too small for any cat. And they used it happily every night.",
        ),
        tale(
            "town-country-mouse", Scene.MEADOW, Mood.CALM, "mouse house mouse",
            "The Town Mouse and the Country Mouse", "A simple life in peace is better than riches in fear.",
            "mouse mouse" to "A town mouse went to visit his cousin in the country. The country mouse gave him the best she had: grains of wheat and fresh water.",
            "mouse mouse" to "“Is this all you eat?” said the town mouse. “Come to the town with me. I have cake and cheese every day.”",
            "mouse house mouse" to "So they went to the big town house. The table was covered with sweet things. The country mouse had never seen so much food.",
            "cat mouse" to "But just as they began to eat, a cat came in. The two mice ran and hid in a hole, their hearts going thump, thump, thump.",
            "mouse" to "“Thank you, cousin,” said the country mouse, “but I am going home.” Back in her quiet field she ate her wheat slowly, and slept without a single worry.",
        ),
        tale(
            "talking-cave", Scene.JUNGLE, Mood.WISDOM, "jackal lion",
            "The Talking Cave", "Stop and think before you walk into danger.",
            "lion" to "A hungry lion found an empty cave. “Some animal must live here,” he thought. “I will hide inside and wait.”",
            "jackal" to "The cave belonged to a jackal. At sunset the jackal came home. Then he saw big paw marks going into the cave, and none coming out.",
            "jackal" to "The jackal stopped and thought. Then he called out, “Hello, cave! Good evening, cave!” The cave was silent.",
            "jackal lion" to "“Cave, why do you not answer me today?” called the jackal. “You always say hello!” The lion thought, “I had better answer.” So he roared, “Hello, jackal!”",
            "jackal" to "The jackal laughed. “Caves cannot talk!” he said, and ran far away to sleep at a friend’s home. The lion went away hungry, feeling rather silly.",
        ),
        tale(
            "stag-pool", Scene.RIVER, Mood.WISDOM, "deer",
            "The Stag at the Pool", "What is useful matters more than what is pretty.",
            "deer" to "A stag came to a pool to drink. In the still water he saw himself. “What beautiful antlers I have,” he said proudly.",
            "deer" to "Then he looked at his legs. “But my legs are so thin,” he sighed. “I wish they were handsome too.”",
            "deer wolf" to "Just then a wolf crept out of the bushes. The stag ran. His thin legs carried him fast, fast across the meadow.",
            "deer oak" to "But in the forest his fine antlers caught in the branches. He pulled and twisted, and at the very last moment he got free.",
            "deer" to "Safe on the hill, the stag looked down at his legs. “Thank you, good legs,” he said. And he never called them ugly again.",
        ),
        tale(
            "wind-sun", Scene.SKY, Mood.KINDNESS, "cloud sun",
            "The Wind and the Sun", "Gentleness wins where force fails.",
            "cloud sun" to "The Wind and the Sun were talking. “I am the stronger one,” said the Wind. “We shall see,” said the Sun with a smile.",
            "boy" to "Far below, a traveller was walking along the road in a warm coat. “Whoever can take off his coat is the stronger,” said the Wind.",
            "cloud boy" to "The Wind blew, and blew, and blew. But the harder it blew, the tighter the traveller held his coat around him.",
            "sun boy" to "Then it was the Sun’s turn. The Sun shone softly and warmly. The traveller smiled and opened his coat. Soon he took it off.",
            "sun cloud" to "“You win,” said the Wind. “Being gentle is strong too,” said the Sun. And they watched the evening come together, the best of friends.",
        ),
        tale(
            "fox-crow", Scene.MEADOW, Mood.WISDOM, "fox crow",
            "The Fox and the Crow", "Be careful of praise from someone who wants something.",
            "crow" to "A crow found a piece of roti and flew up into a tree to eat it. She held it carefully in her beak.",
            "fox crow" to "A fox came by and smelled the roti. “Good morning, lovely crow,” said the fox. “How your feathers shine today!”",
            "fox crow" to "The crow was pleased. “And I am sure your voice is the sweetest in the forest,” said the fox. “Will you sing one song for me?”",
            "crow fox" to "The crow opened her beak to sing. “Caw!” Down fell the roti. The fox caught it and trotted away.",
            "crow" to "The crow sat and thought about it. The next time the fox said sweet things, she kept her beak shut tight, and ate her supper in peace.",
        ),
        tale(
            "donkey-lion-skin", Scene.JUNGLE, Mood.WISDOM, "donkey fox",
            "The Donkey in the Lion’s Skin", "You cannot pretend to be someone else for long.",
            "donkey" to "A donkey found a lion’s skin lying in the forest. “I will put it on,” he thought, “and everyone will think I am a lion.”",
            "donkey rabbit" to "He walked through the forest in the lion’s skin. The rabbits ran. The deer ran. Even the monkeys hid in the trees.",
            "donkey" to "The donkey felt very grand. He was so pleased that he lifted his head and gave a great, proud roar.",
            "donkey fox" to "But the roar came out as “Hee-haw! Hee-haw!” A fox heard it and laughed. “That is no lion. I know that voice. Hello, donkey!”",
            "donkey fox rabbit" to "The donkey took off the skin, feeling shy. “We like you as a donkey,” said the fox. The animals came back, and they all walked home together.",
        ),
        tale(
            "honest-woodcutter", Scene.RIVER, Mood.KINDNESS, "boy sparkle",
            "The Honest Woodcutter", "Honesty is its own reward.",
            "boy" to "A poor woodcutter was cutting wood beside a river. His axe slipped from his hands and fell, splash, into the deep water.",
            "boy sparkle" to "He sat down and wept. Then the river shimmered, and a kind river spirit rose up. “Why are you sad?” the spirit asked.",
            "sparkle boy" to "The spirit dived down and came up with an axe of gold. “Is this yours?” “No,” said the woodcutter. “Mine is not gold.”",
            "sparkle boy" to "The spirit brought up an axe of silver. “Is this one yours?” “No,” he said again. Then the spirit brought up his old iron axe. “Yes! That one is mine.”",
            "boy star" to "“You told the truth every time,” said the spirit, smiling. “Keep all three.” The woodcutter thanked the river and walked home under the first star.",
        ),
        tale(
            "frog-elephant", Scene.RIVER, Mood.CALM, "frog elephant",
            "The Frog Who Wanted to Be Big", "Be happy being exactly who you are.",
            "frog frog" to "A little frog lived by a pond with his mother. One day he saw an elephant come to drink. “How big!” gasped the little frog.",
            "frog" to "“I want to be that big,” he said. He took a deep breath and puffed himself up. “Am I as big now?” “Not yet,” said his mother.",
            "frog" to "He puffed again, and again. His cheeks were round and tight. “Now?” “Not yet. Please stop, little one. You will hurt yourself.”",
            "elephant frog" to "The elephant looked down kindly. “I cannot jump,” she said. “I cannot swim under lily pads. I cannot sing at night. Only a frog can do those things.”",
            "frog frog" to "The little frog let out his breath with a long whoosh. He jumped, and swam, and sang his loudest song. Being a frog, he decided, was just right.",
        ),
        tale(
            "three-fish", Scene.SEA, Mood.WISDOM, "fish lumi fish",
            "The Three Fish", "It is wise to get ready before trouble comes.",
            "fish lumi fish" to "Three fish lived in a quiet pond. One always thought ahead. One was quick and clever. And one liked to say, “We will see. There is no hurry.”",
            "fish fish" to "One evening they heard fishermen talking on the bank. “This pond is full of fish. Let us bring our nets tomorrow.”",
            "lumi" to "The first fish did not wait. That very night she swam down the little stream to the wide river, where she was safe.",
            "fish" to "In the morning the nets came. The second fish thought quickly. He slipped through a gap in the reeds and followed his friend.",
            "fish lumi fish" to "The third fish got a terrible fright and wriggled free at the very last moment. “From now on,” he puffed, “I will get ready early.” And the three friends lived happily in the river.",
        ),
        tale(
            "elephant-dog", Scene.MEADOW, Mood.FRIENDSHIP, "elephant puppy",
            "The Elephant and the Dog", "A true friend is worth more than anything.",
            "elephant puppy" to "A king’s elephant lived in a big stable. One day a little dog wandered in and ate the grains of rice that fell from the elephant’s dinner.",
            "elephant puppy" to "The dog came every day. Soon the two were friends. They ate together, and the dog rode on the elephant’s trunk, swinging up and down.",
            "elephant~" to "Then a farmer took the little dog away to his village. The elephant would not eat. She would not bathe. She only stood and looked at the door.",
            "boy elephant" to "The king’s wise helper watched her. “She is not ill,” he said. “She is missing a friend.” The king sent word across the land: bring back the little dog.",
            "puppy elephant" to "The farmer let the dog go, and he ran all the way to the stable. The elephant lifted him up with her trunk. That night they ate their dinner together again.",
        ),
        tale(
            "monkey-bridge", Scene.RIVER, Mood.COURAGE, "monkey monkey",
            "The Monkey King’s Bridge", "A good leader takes care of everyone.",
            "monkey monkey" to "A troop of monkeys lived in a mango tree beside a river. Their king was big and strong, and he loved every one of them.",
            "boy" to "One day a human king came with his men to pick the mangoes. The monkeys were frightened. There was no way down from the tree.",
            "monkey" to "The monkey king leapt across the river and tied a long vine to a tree on the far bank. But the vine was a little too short.",
            "monkey monkey monkey" to "So he held the vine with his feet and the mango tree with his hands. His own body became the last part of the bridge. One by one, the monkeys ran across his back to safety.",
            "boy monkey" to "The human king watched in wonder. “You carried all your people,” he said. He helped the tired monkey king down, gave him fruit and water, and left the mango tree to the monkeys for ever.",
        ),
        tale(
            "rabbit-moon", Scene.NIGHT, Mood.KINDNESS, "rabbit star",
            "The Rabbit in the Moon", "A generous heart is never forgotten.",
            "rabbit monkey fox" to "A rabbit, a monkey and a fox were friends. “Tomorrow,” said the rabbit, “let us share our food with anyone who is hungry.”",
            "painter" to "The next day a tired old traveller came through the forest. “I have walked so far,” she said. “Has anyone a little food to spare?”",
            "monkey fox painter" to "The monkey brought ripe mangoes. The fox brought a pot of milk. The traveller thanked them both.",
            "rabbit painter" to "The rabbit had only grass, and people do not eat grass. “I have nothing fine to give,” said the rabbit, “but I will stay beside you all night and keep you warm.”",
            "rabbit star" to "The traveller smiled, for she was really a spirit of the sky. “Yours is the kindest gift,” she said. She drew the rabbit’s picture on the moon, and on clear nights you can still see it there.",
        ),
        tale(
            "lion-traveller-jackal", Scene.JUNGLE, Mood.WISDOM, "lion boy jackal",
            "The Lion, the Traveller and the Jackal", "Keep your promises, and think before you trust.",
            "lion" to "A lion was shut inside a strong cage. A traveller walked by. “Please open the door,” begged the lion. “I promise I will not hurt you.”",
            "boy lion" to "The kind traveller opened the cage. Out jumped the lion. “I am hungry,” he growled, “and I have changed my mind.”",
            "jackal boy lion" to "A jackal came along. “What is happening?” The traveller told him. “I do not understand,” said the jackal. “The lion was in the cage? How?”",
            "lion jackal" to "“Like this, you silly jackal!” said the lion, and he stepped back into the cage to show him. Quick as a wink, the jackal shut the door.",
            "boy jackal" to "“Now everything is as it was,” said the jackal. The traveller thanked his clever friend and went on his way, and the lion had a long time to think about promises.",
        ),
        tale(
            "little-hen", Scene.MEADOW, Mood.FRIENDSHIP, "hen cat puppy",
            "The Little Hen and the Wheat", "Those who share the work share the reward.",
            "hen" to "A little hen found some grains of wheat. “Who will help me plant them?” she asked. “Not I,” said the cat. “Not I,” said the dog. So she planted them herself.",
            "hen cat puppy" to "The wheat grew tall and golden. “Who will help me cut it?” “Not I,” yawned the cat. “Not I,” yawned the dog. So she cut it herself.",
            "hen" to "She carried the wheat to the mill and made flour. She mixed the flour and baked a round, warm loaf. The whole yard smelled wonderful.",
            "cat hen puppy" to "“Who will help me eat the bread?” “I will!” said the cat. “I will!” said the dog. The little hen looked at them, and they looked at their feet.",
            "hen cat puppy" to "“Next time we will help,” they said. “Then today we will share,” said the hen. And the next spring, all three planted the wheat together.",
        ),
        tale(
            "donkey-salt", Scene.RIVER, Mood.WISDOM, "capseller donkey",
            "The Donkey and the Salt", "Shortcuts and tricks often make the load heavier.",
            "capseller donkey" to "A merchant had a donkey who carried sacks of salt to the market. On the way they had to cross a shallow river.",
            "donkey" to "One day the donkey slipped and fell in the water. The salt melted away. When he stood up, his load was wonderfully light.",
            "donkey" to "“What a clever trick,” thought the donkey. The next day he fell down in the river on purpose. Again the load grew light.",
            "capseller donkey" to "The merchant understood. The next morning he loaded the donkey with sacks of cotton. In the river, the donkey sat down as before.",
            "donkey capseller" to "But cotton drinks water! The load became twice as heavy. The donkey walked slowly home and never played that trick again. And the merchant gave him an extra carrot for learning.",
        ),
    )
